import type { ProjectId } from "./types";

/**
 * Pocket Gallery: the grand hall. GENERATED by scratch art-tiles/gen-map.mjs.
 *
 * North wall (rows 0-2): werc, bot (centre) and campus hang between two tall
 * windows whose sunbeams fall across the floor. Plinths stand in the room:
 * ramps (west), cnc (east), wave (south-east). The gift shop (shelf, clerk,
 * counter) is in the south-west corner by the doors; the placard is just
 * inside on the right. A cyan runner leads from the doormat to the bot frame.
 *
 * Under each 32 px frame only the tile in front of it is walkable: the other
 * is a stanchion (werc, campus) or a label stand (bot). The clerk's aisle
 * behind the counter is marked solid; the clerk stands in it.
 */
export type Facing = "up" | "down" | "left" | "right";

export interface GalleryMap {
  w: number;
  h: number;
  /** h rows of w chars, each a key of legend. */
  floor: string[];
  /** char -> TILES key */
  legend: Record<string, string>;
  /** PROPS key at the tile coords of the sprite's top-left. */
  props: { id: string; x: number; y: number }[];
  /** h rows: '#' blocked, '.' walkable. */
  solid: string[];
  start: [number, number, Facing];
  /** Where each trainer stands and faces; their sight line runs 3 tiles ahead. */
  trainers: Record<ProjectId, [number, number, Facing]>;
  /** The blocked tile of each work's frame or plinth that the player faces to inspect. */
  works: Record<ProjectId, [number, number]>;
  clerk: [number, number, Facing];
  /** Counter tile; facing it from the tile below talks to the clerk across it. */
  counter: [number, number];
  /** The placard tile. */
  sign: [number, number];
  /** A door tile in the south wall. */
  exit: [number, number];
}

